let cursor=null,placement=null,gizmoMode='translate';
const button=document.createElement('button');button.id='addprimitive';button.textContent='Add shape';button.title='Add blockout shape · Shift+A';button.setAttribute('aria-keyshortcuts','Shift+A');button.setAttribute('aria-haspopup','menu');(document.querySelector('.tools')||$('tool-select').parentElement).append(button);
const menu=document.createElement('div');menu.id='primitive-menu';menu.className='primitive-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Add shape');menu.hidden=true;menu.innerHTML=P.types.map(t=>`<button role="menuitem" data-primitive="${t}">${P.labels[t]}</button>`).join('');document.body.append(menu);
const scope=()=>currentBuilding()?.id+':'+floorId+':'+B.isThreeMode();
