window.addEventListener('pointermove',remember,true);window.addEventListener('pointerdown',remember,true);
function location(){const canvas=B.isThreeMode()?$('threeviewport').querySelector('canvas'):$('plan'),r=canvas?.getBoundingClientRect();if(!r)return null;const e=cursor?.scope===scope()?cursor:{clientX:r.left+r.width/2,clientY:r.top+r.height/2};if(B.isThreeMode())return B.getViewer()?.primitivePlacement?.(e,floorId);const p=point(e);return{x:p.x,y:p.y,z:floor().z??0,normal:{x:0,y:0,z:1}};}
function open(){if(!allowed(floorId)){notify('Choose a visible, editable floor before adding a shape.');return false;}resetTransient(true);setTool('select');closeToolbarMenus();const hit=location();if(!hit){notify('Point into the plan or 3D view to place a shape.');return false;}placement={hit,floor:floorId,building:currentBuilding().id};const r=button.getBoundingClientRect(),p=cursor?.scope===scope()?cursor:{clientX:r.left,clientY:r.bottom};menu.hidden=false;button.setAttribute('aria-expanded','true');const pos=menuPosition(p.clientX,p.clientY,180,180,innerWidth,innerHeight);menu.style.left=pos.x+'px';menu.style.top=pos.y+'px';menu.querySelector('button').focus();return true;}
function add(type){const q=placement;if(!q||q.floor!==floorId||q.building!==currentBuilding().id||!allowed(q.floor)){close();return false;}try{if((floor().primitives||[]).length>=300)throw Error('This floor has reached 300 shapes');const o=P.place(P.create(type,uniqueId('primitive-')),q.hit,floor().z??0),next=clone(model);(next.floors[q.floor].primitives??=[]).push(o);validateImport(next);close();commit(()=>{model=next;setSelection({primitives:[o.id]});});if(B.isThreeMode()){document.body.classList.add('editing3d');$('inspector').hidden=false;document.querySelector('.asidehead').hidden=false;}window.KERN_FOCUS?.canvas();return o.id;}catch(error){notify(error.message);return false;}}
