function menuKey(e){if(menu.hidden||!menu.contains(e.target))return false;const nodes=[...menu.querySelectorAll('button')],i=nodes.indexOf(document.activeElement);if(e.key==='Escape'){stop(e);close(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){stop(e);nodes[e.key==='Home'?0:e.key==='End'?nodes.length-1:(i+(e.key==='ArrowDown'?1:nodes.length-1))%nodes.length].focus();}else{e.stopImmediatePropagation();if((e.ctrlKey||e.metaKey)&&(e.code==='KeyS'||e.key.toLowerCase()==='s'))e.preventDefault();if(e.key==='Tab'){close();button.focus();}}return true;}
menu.addEventListener('keydown',menuKey);
document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&e.target!==button)close();},true);
function selected(){const refs=L.references();return refs.length===1&&refs[0].kind==='primitives'?{ref:refs[0],object:model.floors[refs[0].floor]?.primitives?.find(o=>o.id===refs[0].id)}:null;}
function edit(fid,id,change,baseline){try{if(!allowed(fid)||!L.available('primitives',id,fid))throw Error('Show and unlock this shape’s floor and layer before editing.');const next=clone(model),o=next.floors[fid]?.primitives?.find(o=>o.id===id);if(!o)throw Error('Shape no longer exists');if(baseline&&JSON.stringify(o)!==JSON.stringify(baseline))throw Error('This shape changed during the drag. The drag was cancelled.');Object.assign(o,change);P.validate(o);validateImport(next);if(JSON.stringify(next)===JSON.stringify(model))return true;commit(()=>{model=next;});return true;}catch(error){notify(error.message);render();return false;}}
function select(fid,id,shift=false){const scope=L.floorState(),objectPick=!shift&&scope.active===fid&&scope.selected.length===1&&scope.selected[0]===fid&&L.canEditFloor(fid);L.selectFloor(fid,{additive:shift});if(!objectPick)return true;if(!allowed(fid)||!L.available('primitives',id,fid)){notify('Enable this floor and unlock this layer to edit the shape.');return false;}const result=L.selectLayer('primitives',id,{shiftKey:shift},fid);if(B.isThreeMode()){document.body.classList.add('editing3d');$('inspector').hidden=false;document.querySelector('.asidehead').hidden=false;}return result;}
function setGizmoMode(value){gizmoMode=value;setTool('select');const viewer=B.getViewer();viewer?.selectObjects?.(L.viewerSelection());viewer?.setPrimitiveMode?.(value);primitiveInspector();window.KERN_FOCUS?.canvas();}
function primitiveInspector(){const s=selected();if(!s?.object)return false;const panelKey=currentBuilding().id+':'+s.ref.floor+':'+s.ref.id,orientationOpen=$('inspector').dataset.primitiveId===panelKey&&!!$('primitive-orientation')?.open;$('inspector').dataset.primitiveId=panelKey;const o=s.object,field=(label,k,type='number')=>`<label class="field"><span>${label}</span><input data-primitive-key="${k}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(o[k])}"></label>`;$('selectiontype').textContent=P.labels[o.primitive];$('inspector').dataset.selection='primitive';$('inspector').innerHTML=`<section class="primitive-inspector crossfloor-inspector"><h2>${esc(o.name)}</h2>${field('Name','name','text')}<div class="primitive-gizmo" aria-label="3D shape gizmo">${[['translate','Move'],['scale','Size'],['rotate','Rotate']].map(([v,t])=>`<button data-primitive-mode="${v}" aria-pressed="${gizmoMode===v}">${t}</button>`).join('')}</div><div class="gridfields">${field('X · m','x')}${field('Y · m','y')}${field('Height above '+s.ref.floor+' · m','z')}${field('Width · m','w')}${field('Depth · m','h')}${field('Shape height · m','height')}</div><details id="primitive-orientation" ${orientationOpen?'open':''}><summary>Orientation and colour</summary><div class="gridfields">${field('Turn · °','rotation')}${field('Tilt X · °','tiltX')}${field('Tilt Y · °','tiltY')}</div>${field('Colour','color','color')}</details><div class="object-action-row"><button id="primitive-copy">Copy</button><button id="primitive-duplicate">Duplicate</button><button id="primitive-delete" class="danger">Delete</button></div><p class="small">${esc(s.ref.floor)} · elevation follows this floor. Escape cancels a gizmo drag.</p></section>`;
 $('inspector').querySelectorAll('[data-primitive-key]').forEach(input=>input.onchange=()=>edit(s.ref.floor,o.id,{[input.dataset.primitiveKey]:input.type==='number'?Number(input.value):input.value}));
 $('inspector').querySelectorAll('[data-primitive-mode]').forEach(node=>node.onclick=()=>{setGizmoMode(node.dataset.primitiveMode);});
 $('primitive-copy').onclick=()=>window.KERN_OBJECT_UI.clipboard('c');$('primitive-duplicate').onclick=()=>{if(window.KERN_OBJECT_UI.clipboard('c'))window.KERN_OBJECT_UI.clipboard('v');};$('primitive-delete').onclick=()=>L.removeSelection();return true;
}
const sharedInspector=inspector;inspector=function(...args){return primitiveInspector()||sharedInspector(...args);};
const baseInspector=window.KERN_OBJECT_UI.inspector;window.KERN_OBJECT_UI.inspector=function(){return primitiveInspector()||baseInspector(...arguments);};
const baseMarkup=window.KERN_OBJECT_UI.markup;window.KERN_OBJECT_UI.markup=function(exporting){const s=getSelection();return baseMarkup(...arguments)+(floor().primitives||[]).map(o=>`<g data-extra="primitives" data-id="${esc(o.id)}" class="blockout-shape"><title>${esc(o.name)} · ${P.labels[o.primitive]} · ${o.z} m above ${esc(floorId)}</title><path d="M${P.points(o).map(p=>p.join(' ')).join('L')}Z" fill="${o.color}" fill-opacity="${s.primitives?.includes(o.id)&&!exporting?.5:.25}" stroke="${o.color}" stroke-width=".065" pointer-events="all"/></g>`).join('');};
function handleKey(e){if(window.KERN_KEYS.typing(e.target)||window.KERN_WORKSPACE?.isHome()||window.KERN_EXPLORER?.active||document.querySelector('dialog[open]'))return false;const k=String(e.key).toLowerCase(),mod=e.ctrlKey!==e.metaKey;if(B.isThreeMode()&&selected()&&k==='e'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey){stop(e);if(!e.repeat)setGizmoMode('rotate');return true;}if(k==='a'&&e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey){stop(e);if(!e.repeat)open();return true;}if(e.key==='Escape'&&(!menu.hidden||B.getViewer()?.primitiveDragging?.())){stop(e);close(true);B.getViewer()?.cancelPrimitive?.();return true;}if(mod&&!e.altKey&&['z','y'].includes(k)&&B.getViewer()?.primitiveDragging?.()){stop(e);B.getViewer().cancelPrimitive();return true;}const refs=L.references();if(B.isThreeMode()&&refs.some(r=>r.kind==='primitives')&&!e.altKey){if(mod&&!e.shiftKey&&['c','x','v'].includes(k)){stop(e);if(!e.repeat)window.KERN_OBJECT_UI.clipboard(k);return true;}if(!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&['delete','backspace'].includes(k)){stop(e);if(!e.repeat)L.removeSelection();return true;}}return false;}
const rotateClick=$('tool-rotate').onclick;$('tool-rotate').onclick=function(e){if(B.isThreeMode()&&selected())return setGizmoMode('rotate');return rotateClick.call(this,e);};
const oldRender=render;render=function(...args){if(placement&&(placement.floor!==floorId||placement.building!==currentBuilding().id))close();const r=oldRender(...args);button.hidden=window.KERN_WORKSPACE?.isHome()||false;return r;};
